class NameError;def missing_name;message=respond_to?(:original_message) ? original_message: self.message;return unless message.start_with?("uninitialized constant ");receiver=begin self.receiver;rescue ArgumentError;nil;end;if receiver==Object;name.to_s;elsif receiver;"#{real_mod_name(receiver)}::#{self.name}";else if match=message.match(/((::)?([A-Z]\w*)(::[A-Z]\w*)*)$/);match[1];end;end;end;def missing_name?(name)if name.is_a?Symbol;self.name==name;else missing_name==name.to_s;end;end;private;UNBOUND_METHOD_MODULE_NAME=Module.instance_method(:name);private_constant:UNBOUND_METHOD_MODULE_NAME;def real_mod_name(mod)UNBOUND_METHOD_MODULE_NAME.bind_call(mod);end;end
